NAME = 'sml_BL_2008: Kitab Awal-Jaman maka Kitab Injil'
BOOK = 'James'

CHAPTERS = {
    1: {
        1: "Sulat itu min aku si Yakub, a'a sosoho'an Tuhan maka si Isa Al-Masi Panghū'tam. Magaddat aku ma ka'am saga pagkahiku Yahudi, a'a suku' Tuhan apulak-palik ma kaluha'an dunya.",
        2: "Saga dauranakanku, bang kam taluwa' kasukkalan indaginis, subay kam kinōgan.",
        3: "Sabab kata'uwanbi, bang pangandolbi pinalabayan kasukkalan bo' kaimananbi, gom pa'in pasōng tatasbi anandalan ai-ai.",
        4: "Puspusinbi kosogbi anandalan kasukkalan bo' supaya kam asangpot ma kaul maka pi'il, ma halam aniya' kulangbi.",
        5: "Sagō' bang aniya' ma ka'am akulang pangita'una, subay iya angamu'-ngamu' ni Tuhan ati tantu iya kabuwanan pangita'u, sabab magmura asal Tuhan ma a'a kamemon. Mbal iya an'ndal bang pangamu'an.",
        6: "Saguwā' bang kam ganta' angamu' ai-ai ni Tuhan, subay kam am'nnal ma iya ma halam aniya' pagduwa-duwabi. Sasuku magāng-āng pangandolbi ni Tuhan, ibarat kam sahal goyak tabowa pehē'-pi'itu e' baliyu.",
        7: "Da'a kam aholat pinasambutan ai-ai e' Panghū',",
        8: "sabab bang a'a magduwa-ruwa pikilanna mbal ahantap pamikilna.",
        9: "Bang saupama aniya' pagkahitam sōd si Isa kamiskinan, subay iya kinōgan sabab pinalanga du iya e' Tuhan.",
        10: "Damikiyanna bang aniya' a'a sōd si Isa taga-karaya, subay iya kinōgan bang pinareyo' e' Tuhan, sabab minsan a'a dayahan pahalam du isab ibarat sumping kasagmotan.",
        11: "Makasilak pa'in llaw, magtūy alanos kasagmotan e' pasu' llaw he'. Apakpak sumpingna ati pahalam bay manisna. Buwattē' du isab bang a'a dayahan. Kosog-kosogan pa'in iya angusaha, amatay du iya ati ka'bbahan du pagusahana.",
        12: "Aheya du kahāpan a'a bang mbal alungay pangandolna minsan iya anandalan kasukkalan. Sababna bang mbal apinda pangandolna minsan ma deyom kasukkalan, pinaniya'an du iya kallum kakkal ni kasaumulan. Ya na itu tungbas panganjanji' Tuhan ma sasuku alasa ma iya.",
        13: "Bang kam ganta' sinasat maghinang la'at, da'a bīnginbi Tuhan. Da'a yukbi Tuhan ya anasat ka'am inān, sabab in Tuhan mbal tasasat maka mbal isab iya anasat.",
        14: "Sagō' napsu manusiya' ya amowa-mowa iya maghinang kala'atan. Napsuna sali' dalil umpan angati iya maghinang dusa.",
        15: "Ma tagna'anna, aniya' kinanapsuhan e' a'a, ma deyom pikilanna sadja. Mbal at'ggol magbuwa' du napsu inān, jari dusa ya buwa'na. Bang karuhunan dusa inān, nalka' ya kamattihanna.",
        16: "Angkanna, saga danakan kalasahanku, da'a palinguhunbi pikilanbi.",
        17: "Saga lidjiki' kamemon maka ai-ai halam aniya' salla'na ya pamuwan kitam, patulun asal min sulga', min Tuhan magpapanjari saga sawa ya anahaya ma b'ttong langit. Magkapinda sawa inān sagō' mbal magkapinda Tuhan maka mbal amuwan landung.",
        18: "Min kabaya'anna angkan kitam nihinang anakna pagka kahagadtam lapal palmanna. Ya kabaya'anna in kitam saga anakna subay pinabangsa labi gi' min bangsa ai-ai bay papanjarina.",
        19: "Amay-amay, saga dauranakan kalasahanku, subay kitam pakale pahāp maka subay mbal magdai'-dai' amissala. Subay kitam mbal al'kkas angastol,",
        20: "sabab bang a'a angastol mbal tahinangna saga hinang ahāp ya kinabaya'an e' Tuhan.",
        21: "Angkan subay la'ananbi kamemon ya makalumu' ataybi, maka subay bbahanbi saga hinang ala'at ya mamarahi hekana ilu. Pareyo'unbi ataybi tudju ni Tuhan, maka taima'unbi lapal palmanna, ya sali' dalil binhi' tinanom e'na ma deyom pangatayanbi. Sabab palman Tuhan ya sababanna angkan kam lappasan min hukuman dusa.",
        22: "Da'a kam hal akale ma palman Tuhan. Ikutunbi panoho'anna. Bang kalebi bo' mbal hinangbi, angakkalan kam di-bi.",
        23: "Bang a'a ganta' hal akale ma palman Tuhan, bo' mbal ameya' ma panoho'anna, in a'a inān ibarat a'a ananding pangluwahanna ma samin.",
        24: "Aubus pa'in e'na ananding, ala'an iya min atag ina'an ati takalipatna magtūy bang buwattingga pangluwahanna.",
        25: "Samin itu ibarat sara' Tuhan ya halam aniya' salla'na, sara' makapaluhaya ma manusiya'. Maka a'a ang'nda' ma samin itu ibarat a'a angadji' na pa'in ma sara' inān. Mbal takalipatna sagō' bineya' e'na bay ta'adji'na, jari tantu iya kabuwanan kahāpan e' Tuhan minsan ai hinangna.",
        26: "Bang aniya' a'a amikilan di-na in iya bal-agama, bo' mbal tapaggatna d'lla'na amissala ala'at, a'a inān angakkalan di-na. Halam aniya' kapūsan pagagamana.",
        27: "Bang ma Mma'tam Tuhan, ya na itu pagagama halam aniya' lamudna ala'at: kaissana, subay tabangta saga anak-ilu' maka saga balu d'nda bang sigām ma deyom kasigpitan. Karuwana, subay kita angahalli'an di-ta bo' kita mbal tabowa anunuran saga addat ala'at maitu ma dunya.",
    },
    2: {
        1: "Saga dauranakanku, pagka kam ameya' ma si Isa Al-Masi, ya Panghū'tam bangsahan, subay mbal papagbidda'bi a'a minsan sai-na.",
        2: "Saupama aniya' duwangan a'a pasōd ni deyom pagtimukanbi, dakayu' inān dayahan magsingsing bulawan maka mags'mmek ahalga', bo' dakayu' inān miskin, ndang asal s'mmekna.",
        3: "Saupama palabi pagaddatbi ma a'a ahalga' s'mmekna, ati yukbi ma iya, “Tuwan, aningkō' ka kono' ma tingkō'an ahāp itu.” Sagō' yukbi ni a'a miskin e', “An'ngge sadja ka mailu,” atawa “Aningkō' ka maitu ma lantay, ma atag tape'ku”.",
        4: "Na, bang buwattē' hinangbi, asā' kam pagka papagbidda'bi saga pagkahibi bebeya'an si Isa. Ala'at deyom pikilanbi, pagka yukbi alanga dakayu', bo' areyo' dakayu'.",
        5: "Pakale kam, saga dauranakanku kinalasahan. Tapene' asal e' Tuhan saga a'a ya binista miskin ma dunya itu, bo' aniya' karaya sigām b'nnal, hatina pangandol sigām ma iya. Pinene' isab sigām bo' binuwanan palsuku'an ma deyom pagparintahanna, buwat asal panganjanji'na ma sasuku alasahan iya.",
        6: "Sagō' ilu pagtunggīnganbi saga a'a miskin! Sai bahā' anigpitan ka'am, maka sai anukbalan ka'am ni pagsara'an? A'a dayahan ko' he'.",
        7: "Sai bahā' amissalahan la'at ma pasal ōn bangsahan ya pangōn tag-suku' ma ka'am? A'a dayahan!",
        8: "Ahāp hinangbi bang beya'bi to'ongan sara' Tuhan, sara' umbul dakayu'. Tasulat asal sara' itu ma deyom Kitab, ya yuk-i, “Kalasahinbi pagkahibi buwat e'bi alasahan baranbi.”",
        9: "Sagō' bang papagbidda'bi a'a ma sabab luwana, makarusa kam, maka taluwa' kam hukuman sabab langgal sara' kam.",
        10: "Sara' Tuhan itu, minsan bogboganbi kaheka'anna bo' pa'in lakaranbi hal dakayu', talanggalbi du kamemonna.",
        11: "Sabab yuk Tuhan ma deyom sara'na, “Da'a ka angaliyu-lakad ni ngga'i ka paghola'nu,” maka yukna isab, “Da'a ka amapatay”. Manjari minsan kam mbal angaliyu-lakad, bo' amapatay kam, masi du talanggalbi sara' Tuhan.",
        12: "Subay kitam ahantap ma kaul maka pi'il sabab sinara' kitam ma sara' ya makabuwan kalimayahan.",
        13: "Sabab bang Tuhan ya angahukum ma manusiya', bo' aniya' a'a halam bay ma'ase' ma pagkahina, mbal du isab kina'ase'an e' Tuhan. Saguwā' bang a'a ma'ase' ma pagkahina, mbal iya tināw sinara' sabab ma'ase' du Tuhan ma iya.",
        14: "Saga dauranakanku, bang aniya' a'a ganta' ah'lling in iya angandol ma Tuhan, bo' mbal taluwa' saga hinangna, pangandolna inān halam aniya' pūsna, maka halam aniya' dapat makalappas iya min hukuman dusa.",
        15: "Saupama aniya' pagkahibi bebeya'an si Isa kulang-kabus ma pan'mmek maka ma pagkakan,",
        16: "ai kapūsanna bang hal yukbi ni sigām, “Mura-murahan, bang pa'in ahāp kahālanbi. Mags'mmek kam akapal bo' kam mbal nihaggut! Amangan kam pahāp!” Bang kam hal amissala sadja bo' mbal amuwan ai-ai panabangbi kulang-kabus sigām, na, tantu halam aniya' pūsna.",
        17: "Damikiyanna bang takdil ni pangandol. Bang yukbi in ka'am angandol ma Tuhan, bo' halam aniya' hinangbi ahāp tumabeya', mbal b'nnal pangandolbi.",
        18: "Kalu aniya' anganjawab, yuk-i, “Aniya' angandol ma Tuhan, aniya' maghinang kahāpan.” Na, bang buwattē' panganjawabna, buwattitu panambungku, “Pa'nda'in aku pangandolnu ma halam aniya' hinang tumabeya' tanda' saksi', ati pa'nda'anta ka pangandolku luwas min kahinanganku ahāp.”",
        19: "Am'nnal ka bahā' in Tuhan dakayu' du? Na, ahāp isab. Sagō' minsan saga saitan, am'nnal isab sigām in Tuhan dakayu' du, ati amidpid sigām sabab min tāw sigām.",
        20: "Dupang pahāp ka! Bilahi ka bahā' kab'nnalan pasal pangandolta halam aniya' pūsna bang mbal pinabeya'an kahinangan ahāp?",
        21: "Pikilun si Ibrahim ya ka'mbo'-mbo'antam. Angkan iya bay binista abontol e' Tuhan ma sabab tahinang e'na panoho'an Tuhan. Bay tukbalanna ni Tuhan anakna si Isa'ak, pinat'nna' e'na ma diyata' batu pagkulban.",
        22: "Mbal bahā' tahatinu? Ya pangandol si Ibrahim inān bay magbeya' maka hinangna. Min hinangna angkan jukup pangandolna ma Tuhan.",
        23: "Jari tahatita na in bay tasulat ma deyom Kitab pasal si Ibrahim, ya yuk-i, “Si Ibrahim bay am'nnal ma Tuhan, ati binista iya abontol e' Tuhan sabab min kapam'nnalna.” Angkan iya bay kaōnan bagay Tuhan.",
        24: "Na, minnē' kata'uwannu in kitam itu binista abontol e' Tuhan bang aniya' isab hinangta ahāp. Mbal jukup bang kita hal angandol. In pangandolta subay magbeya' maka hinangta.",
        25: "Buwattē' isab si Rahab, d'nda pagtatambahan ma masa awal e'. Sagō' binista iya abontol e' Tuhan ma sabab hinangna ahāp. Bay patuntulna saga mata-mata bangsa Isra'il bay pina'an anganyata' lahatna. Pinandu'an sigā e'na lān saddī pamole'an sigā.",
        26: "Manjari in pangandolta ma Tuhan sapantun baran, amatay bang halam aniya' napasna. Damikiyanna pangandolta ma Tuhan, amatay isāb bang halam aniya' kahinangan ahāp tumabeya'.",
    },
    3: {
        1: "Saga dauranakanku, subay mbal aheka min ka'am angangut nihinang guru. Sabab kata'uwanbi in kami saga guru, bang asā' pamandu' kami, labi abuhat in hukuman ya pinat'nna'an kami e' Tuhan min saga a'a ngga'i ka guru.",
        2: "In kitam manusiya', araran magkasā'. Bang aniya' a'a mbal to'ongan asā' ma bissalana, tubus na a'a inān ma kaul maka pi'il, maka kapagagihanna kabaya'an baranna.",
        3: "Ya dalilna kakkang kura'. Sangonanta kakkang itu ni bowa' kura' bo' ameya' ma panoho'anta, ati kapagbaya'anta pi'ingga-pi'ingga.",
        4: "Dalilna isab bansān ma kappal leha'an. Minsan aheya baran kappal, maka minsan akosog baliyu, maka minsan ariki' isab bansān, in kappal inān tabowa patudju pi'ingga-pi'ingga ya kinabaya'an e' a'a amansān.",
        5: "Buwattē' isab hatulan d'lla'ta itu. Minsan b'nnal ariki', tantu aheya hinangna. Pikilunbi api. Minsan hal keyat ariki', tantu makaralletan gulangan aluha.",
        6: "Na, api itu pangandalilan d'lla'ta, sabab d'lla'ta ya makatagna'an ginisan kala'atan. Dakayu' du d'lla' ma baranta, sagō' bang itu palagtik na, tabowa katibu'ukan baranta ni kala'atan. T'ggolta allum, in d'lla'ta itu amuwanan kita kasusahan. Ya dalilna api luwas bay min nalka'.",
        7: "Binangsa kaginisan, sattuwa talun maka manuk-manuk, daing isab maka sowa, takole' pinagbaya'an e' manusiya'.",
        8: "Saguwā' d'lla' itu, halam aniya' makapagbaya'an iya. Halam aniya' hondongan la'atna, ap'nno' asal e' lassun makapatay.",
        9: "D'lla'ta ya ginuna pamudjita Panghū'ta Tuhan, ya Mma'tam. Maka d'lla'ta isab ya ginuna panukna'ta pagkahita manusiya', ya bay pinapanjari e' Tuhan ma buwat kajarihanna.",
        10: "Hatina dakayu' du bowa' ya paluwasan bissala pamudji maka bissala panukna'. Saga dauranakanku, subay kita da'a buwattē'.",
        11: "Aniya' bahā' bohe' ahāp maka bohe' at'bbag magbeya' paluwas min dakayu' tuburan?",
        12: "Tantu halam. Saga dauranakanku, aniya' bahā' kayu igira amuwan buwa' jaitun? Aniya' bahā' bahan anggul amuwan buwa' igira? Tantu halam. Damikiyanna, mbal ka makasauk bohe' ahāp min pagbohe'an at'bbag.",
        13: "Bang aniya' mailu ma ka'am a'a alalom pangita'una maka ahāp panghatina, subay manyatakan ma kahāp tebong a'a ilu in iya taga-pangita'u. Subay areyo' pangatayanna maka subay alalom pikilanna bo' maghinang ahāp.",
        14: "Sagō' ka'am ilu, bang ala'at deyom hona'-hona'bi bo' kam angandali'it ma sehe'bi, maka bang hal kahāpan baranbi ya kannalbi, da'a kam magbantug-bantug di-bi in ka'am taga-kata'u. Da'a paliluhinbi dusabi.",
        15: "Min dunya sadja saga hona'-hona' buwattē', min pikilan manusiya' maka min saitan. Ngga'i ka buwattē' bang pangita'u min Tuhan.",
        16: "Sabab maingga-maingga lahat, bang aniya' saga a'ana angandali'it maka hal angannal ma kahāpan baran sigām, tantu aniya' maina'an kasasawan maka ginisan la'at kamemon.",
        17: "Sagō' bang a'a taga-pangita'u min Tuhan buwattitu kahālanna: kaissana, halam aniya' tamak atayna. Karuwana, aluhay iya binowa magsulut bang aniya' pagsagga'an. Ahāp bowahanna ni a'a kamemon, maka ahanunus iya. Ma'ase' iya, maka biyaksa iya maghinang ahāp ma pagkahina. Magtaluwa' hinangna maka lling bowa'na, maka mbal iya amapagbidda' a'a minsan sai.",
        18: "Sasuku a'a amapagkahāp sehe'na, sali' dalil a'a magtanom. Kabontolan atay ya ta'ā'na min tinanomna, pagka patisulutun iya maka mbal pangalulugat.",
    },
    4: {
        1: "Ai po'onna angkan kam araran magsagga' maka maglugat? Min napsubi ko' ilu, ya magkosog-kosogan na pa'in ma deyom ataybi.",
        2: "Aniya' kabaya'anbi sagō' mbal ta'ā'bi, angkan kam bilahi amapatay. Aniya' kanapsuhanbi sagō' mbal kam karūlan, angkan kam magsagga' maka magbono'. Mbal kam pinaniya'an ai-ai ya kabaya'anbi, sabab mbal kam angamu' ni Tuhan.",
        3: "Maka minsan isab amu'bi, mbal kam binuwanan sabab ala'at kōkbi. Tu'ud kam bilahi magparūl napsubi, angkan kam angamu'.",
        4: "Ka'am ilu sali' sapantun a'a angaliyu-lakad ni ngga'i ka paghola'na. Halam bahā' kata'uwanbi? Sasuku amanuyu' ma kala'atan ai-ai ma dunya itu, kab'nsihanna Tuhan. Maka sasuku ka'amuhan ma addat-tabi'at ya sinunuran ma dunya itu, bantahanna Tuhan.",
        5: "Marai' pangannalbi mbal b'nnal ya tasulat ma deyom Kitab, ya yuk-i, “In ginhawa bay pinat'nna' e' Tuhan ma deyom baranta akosog asal magnapsu.”",
        6: "Sagō' akosog lagi' tabang Tuhan ma kita min saga napsu ya amowa-mowa baranta, buwat bay tasulat ma deyom Kitab, ya yuk-i, “Sinagga' e' Tuhan saga a'a alanga atayna, sagō' tinabangan e'na saga a'a areyo' atayna.”",
        7: "Angkan kam subay magmaluluy sadja ma kabaya'an Tuhan. Paggatunbi nakura' saitan ati alahi du iya min ka'am.",
        8: "Pasekot kam ni Tuhan ati sinekot kam isab e'na. Ka'am saga dusahan ilu, bbahinbi saga hinangbi ala'at. Ka'am isab, ya mbal magtaluwa' hinangbi maka llingbi, sussihunbi deyom ataybi.",
        9: "Kasukkalinbi saga kala'atan ya tahinangbi. Magkarukka'an kam maka magtangis. Ya pagtittowabi maka kakōganbi subay pininda ni kasusahan.",
        10: "Pareyo'unbi ataybi tudju ni Panghū' ati pinalanga du kam e'na.",
        11: "Saga dauranakanku, da'a kam angalimut kasehe'anbi. Sabab sasuku angalimut atawa anoway danakanna bebeya'an si Isa, sali' sara' Tuhan maka kahandakna ya sowayna. Jari bang kam ganta' anoway kahandak Tuhan, tantu mbal beya'bi sabab yukbi aniya' sā'na.",
        12: "Dakayu'-kayu' Tuhan ya amat'nna' sara' maka angahukum. Tunggal du iya ya angalappas maka tunggal iya amowa ni kamulahan. Angkan halam aniya' kapatutbi anoway pagkahibi manusiya'.",
        13: "Pakale kam sasuku kam magpangupama pasal llaw sinōng. Yukbi, “Salung atawa simuddai pehē' du kami ni da'ira ina'an-i ati pahanti' kami dantahun maina'an maglitu supaya aheka sīn paluntungan kami.”",
        14: "Malaingkan mbal kata'uwanbi bang ai pat'kka ni ka'am salung! Kallumbi ma dunya itu sali' dalil husbu. Dai'-dai' du ta'nda', magtūy palanyap.",
        15: "Angkan subay buwattitu pah'llingbi, “Bang min kabaya'an Panghū', allum gi' kami ati makahinang itu-ini.”",
        16: "Sagō' ka'am ilu, alanga ataybi maka abbuhan kam. Bo' arapun in pagabbu buwattilu ala'at kamemon.",
        17: "Manjari sai-sai ata'uwan hinang ahāp bo' mbal hinangna, taga-dusa du iya.",
    },
    5: {
        1: "Na, ka'am saga a'a dayahan, pakale na kam ma aku. Subay kam magpanangis, subay kam maglemong, ma sabab kasukkalan ya song pat'kka ni ka'am.",
        2: "Magka'at na alta'bi, maka s'mmekbi ahāp aubus bay kinakan e' ulat.",
        3: "Saga bulawanbi maka pilakbi anawasa' na ma deyom tau'an. Jari in sawasa' inān tanda' saksi' in ka'am bay anipun alta' paheka ma llaw kahinapusan dunya itu. Taka-taka in alta'bi inān sapantun api amangan isibi.",
        4: "Dayahan kam, sagō' halam kagadjihanbi saga a'a maghinang ma kahuma'anbi. Kalehunbi pangandahing saga a'a bay soho'bi animuk buwa' min tana'bi. Wa'i pasampay pangandahing sigām ni Tuhan Sangat Kawasa.",
        5: "Ka'am saga dayahan, kabiyaksahan kam maghāp palasahan maka angandūlan napsubi. Ibarat kam sapi' hal amahambug di-na, bo' mbal kata'uwanna song waktu panumbali' iya.",
        6: "Bay hukumbi maka papataybi saga a'a halam taga-dusa, minsan sigām halam bay anagga' ka'am.",
        7: "Angkanna, saga dauranakanku, tatasinbi ai-ai makani-ka'am sat'ggol mbal pabīng Panghū'tam si Isa Al-Masi. Pikilunbi a'a maghuma, atatas iya angagaran waktu pagbuwa' tana'na, sabab ahalga' asal buwa'na ma iya. Mbal iya sinumu angagaran kat'kka ulan, ulan pagararu maka ulan pamatahak pai.",
        8: "Damikiyanna isab ka'am, subay kam mbal sinumu angagad. Pahogotunbi ataybi sabab asekot na waktu papi'itu Panghū'tam.",
        9: "Saga dauranakanku, da'a pagmusmurinbi sehe'bi bebeya'an si Isa Al-Masi, bo' kam mbal taluwa' hukuman Tuhan. Ilu na ya maghuhukum, asekot na to'ongan.",
        10: "Saga dauranakanku, pikilunbi saga nabi, ya bay amowa lapal deyo' min Panghū' ma masa awal e'. Panunurinbi sigām, pagka sigām bay atuyu' angiman ma deyom kabinasahan.",
        11: "Bang ma bistahanta, taga-kahāpan asal saga a'a makatatas buwattē'. Takalebi pasal kasandal si Ayyub waktuna ma deyom kasusahan. Kata'uwanbi isab kamaujuranna, ahāp bay panungbas Panghū' ma iya. Sabab landu' patiase'un maka patilasahun Panghū'tam.",
        12: "Saga dauranakanku, ahalga' pamituwaku itu min kamemon: bang aniya' bissalabi da'a kam magsapa. Da'a sibahatunbi sulga' atawa dunya atawa ai-ai saddī pagsapahanbi. Magaho' sadja kam bang subay aho'. Mag'mbal isab bang subay mbal. Da'a palabihunbi minnē', bo' kam mbal taluwa' hukuman Tuhan.",
        13: "Abila aniya' a'a mailu ma ka'am t'kkahan kasusahan, subay iya angamu' tabang ni Tuhan. Abila isab aniya' ma ka'am kinōgan, subay iya angalang saga kalangan pamudjina Tuhan.",
        14: "Abila aniya' ma ka'am taga-saki, subay tambukuhanna saga pagmatto'ahan ma palhimpunan si Isa Al-Masi mailu. Ati saga matto'a inān subay angamu'-ngamu' ni Tuhan ma kamaina'anan a'a sakihan, maka subay sigām anapu iya maka ns'llan ma salta' sigām anabbut ōn Panghū'tam.",
        15: "Manjari itu, bang sigām angamu'-ngamu', bo' ahogot asal pangandol sigām ma Tuhan, a'a inān kauli'an du. Niuli'an du iya e' Panghū', maka bang aniya' dusana, niampun du.",
        16: "Angkan yukku ma ka'am, magpasab'nnal kam pasal saga dusabi ni pagkahibi bebeya'an si Isa Al-Masi. Amu'inbi isab tabang ni Tuhan ma sabab pagkahibi dangan maka dangan, bo' supaya kam kauli'an. Bang a'a abontol angamu' ni Tuhan min deyom atayna, abarakat to'ongan pangamu'na.",
        17: "Si Nabi Elija e', manusiya' du buwat kitam. Bay iya anabbut Tuhan min deyom atayna ma masa awal e', angamu' subay mbal angulan. Jari halam to'ongan aniya' ulan am'ttak ni lahat inān ma deyom t'lluntahun maka tonga'.",
        18: "Puwas e' bay iya angamu'-ngamu' pabalik subay aniya' ulan. Angulan magtūy, jari magbuwa' saga tinanom.",
        19: "Na, saga dauranakanku, abila aniya' min ka'am pasiha' min pandu' b'nnal, bo' aniya' a'a dangan amowa iya ameya' ma pandu' b'nnal pabalik, ahāp ko' he'.",
        20: "Tau'unbi itu ma deyom pikilanbi: sai-sai makabowa a'a dusahan ang'bba min kasā'anna, lappasan e'na a'a dusahan inān bo' mbal pinehē' ni deyom nalka', ati ta'ampun du paldusahanna aheka. Wassalam",
    },
}
